//! Abstract syntax tree for the regular expression dialect understood by `srgn`.

/// A single member of a character class: either a plain character or an
/// inclusive range.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ClassItem {
    Single(char),
    Range(char, char),
}

/// One of the shorthand/property based class predicates. These are kept
/// symbolic instead of being expanded into ranges: expansion would need the
/// full Unicode character database, while a predicate only needs the handful of
/// classification functions the standard library already provides.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ClassPred {
    Digit,
    Word,
    Space,
    Alpha,
    Alnum,
    Upper,
    Lower,
    Punct,
    Graph,
    Print,
    Blank,
    Cntrl,
    XDigit,
    Ascii,
    /// A `\p{..}` style Unicode property, stored by its (normalised) name.
    Unicode(UnicodeProp),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum UnicodeProp {
    Letter,
    LetterUpper,
    LetterLower,
    LetterTitle,
    LetterModifier,
    LetterOther,
    Mark,
    Number,
    NumberDecimal,
    Punctuation,
    Symbol,
    Separator,
    SeparatorSpace,
    Other,
    Control,
    Whitespace,
    Alphabetic,
    Latin,
    Greek,
    Cyrillic,
    Han,
    Arabic,
    Hebrew,
    Hiragana,
    Katakana,
    Any,
}

/// A character class, i.e. `[...]` or one of the shorthands such as `\d`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Class {
    pub negated: bool,
    pub items: Vec<ClassItem>,
    /// Positive predicates; a character matches when any of them holds.
    pub preds: Vec<ClassPred>,
    /// Negated predicates (e.g. `\D` nested inside a class).
    pub neg_preds: Vec<ClassPred>,
    pub case_insensitive: bool,
}

impl Class {
    pub fn new(negated: bool, case_insensitive: bool) -> Self {
        Self {
            negated,
            items: Vec::new(),
            preds: Vec::new(),
            neg_preds: Vec::new(),
            case_insensitive,
        }
    }

    pub fn matches(&self, c: char) -> bool {
        let hit = self.matches_positive(c)
            || (self.case_insensitive && {
                // Try the other casings of the character. Folding both ways
                // keeps things simple and covers the (few) multi-char cases by
                // ignoring them.
                let mut found = false;
                for alt in fold_variants(c) {
                    if alt != c && self.matches_positive(alt) {
                        found = true;
                        break;
                    }
                }
                found
            });
        hit != self.negated
    }

    fn matches_positive(&self, c: char) -> bool {
        for item in &self.items {
            match *item {
                ClassItem::Single(s) => {
                    if s == c {
                        return true;
                    }
                }
                ClassItem::Range(lo, hi) => {
                    if c >= lo && c <= hi {
                        return true;
                    }
                }
            }
        }
        for p in &self.preds {
            if pred_matches(p, c) {
                return true;
            }
        }
        for p in &self.neg_preds {
            if !pred_matches(p, c) {
                return true;
            }
        }
        false
    }
}

/// All casings of `c` worth trying for case-insensitive comparisons.
pub fn fold_variants(c: char) -> Vec<char> {
    let mut out = vec![c];
    let mut lower = c.to_lowercase();
    if lower.len() == 1 {
        let l = lower.next().unwrap();
        if !out.contains(&l) {
            out.push(l);
        }
    }
    let mut upper = c.to_uppercase();
    if upper.len() == 1 {
        let u = upper.next().unwrap();
        if !out.contains(&u) {
            out.push(u);
        }
    }
    // A few characters fold to a third form (e.g. Kelvin sign / long s).
    match c {
        'ſ' => out.push('s'),
        'K' | 'k' => out.push('\u{212a}'),
        'Å' | 'å' => out.push('\u{212b}'),
        '\u{212a}' => {
            out.push('k');
            out.push('K');
        }
        '\u{212b}' => {
            out.push('å');
            out.push('Å');
        }
        _ => {}
    }
    out
}

fn pred_matches(p: &ClassPred, c: char) -> bool {
    match p {
        ClassPred::Digit => c.is_ascii_digit() || (!c.is_ascii() && c.is_numeric() && is_decimal(c)),
        ClassPred::Word => c.is_alphanumeric() || c == '_' || is_mark(c) || is_connector(c),
        ClassPred::Space => is_regex_space(c),
        ClassPred::Alpha => c.is_alphabetic(),
        ClassPred::Alnum => c.is_alphanumeric(),
        ClassPred::Upper => c.is_uppercase(),
        ClassPred::Lower => c.is_lowercase(),
        ClassPred::Punct => is_punct_or_symbol(c),
        ClassPred::Graph => !c.is_whitespace() && !c.is_control() && c != '\u{0}',
        ClassPred::Print => (!c.is_control()) && c != '\u{0}',
        ClassPred::Blank => c == ' ' || c == '\t',
        ClassPred::Cntrl => c.is_control(),
        ClassPred::XDigit => c.is_ascii_hexdigit(),
        ClassPred::Ascii => c.is_ascii(),
        ClassPred::Unicode(u) => unicode_prop_matches(*u, c),
    }
}

fn is_decimal(c: char) -> bool {
    c.is_numeric() && c.to_digit(10).is_some() || matches!(c, '\u{0660}'..='\u{0669}' | '\u{06f0}'..='\u{06f9}' | '\u{0966}'..='\u{096f}' | '\u{ff10}'..='\u{ff19}')
}

pub fn is_regex_space(c: char) -> bool {
    matches!(c, ' ' | '\t' | '\n' | '\r' | '\u{b}' | '\u{c}') || (!c.is_ascii() && c.is_whitespace())
}

pub fn is_mark(c: char) -> bool {
    matches!(c,
        '\u{0300}'..='\u{036f}' | '\u{0483}'..='\u{0489}' | '\u{0591}'..='\u{05bd}'
        | '\u{0610}'..='\u{061a}' | '\u{064b}'..='\u{065f}' | '\u{0670}'
        | '\u{06d6}'..='\u{06dc}' | '\u{0900}'..='\u{0903}' | '\u{093a}'..='\u{094f}'
        | '\u{0951}'..='\u{0957}' | '\u{0e31}' | '\u{0e34}'..='\u{0e3a}'
        | '\u{0e47}'..='\u{0e4e}' | '\u{1ab0}'..='\u{1aff}' | '\u{1dc0}'..='\u{1dff}'
        | '\u{20d0}'..='\u{20f0}' | '\u{fe20}'..='\u{fe2f}')
}

fn is_connector(c: char) -> bool {
    matches!(c, '_' | '\u{203f}' | '\u{2040}' | '\u{2054}' | '\u{fe33}' | '\u{fe34}' | '\u{fe4d}'..='\u{fe4f}' | '\u{ff3f}')
}

pub fn is_punct_char(c: char) -> bool {
    if c.is_ascii() {
        return c.is_ascii_punctuation();
    }
    matches!(c,
        '\u{00a1}' | '\u{00a7}' | '\u{00ab}' | '\u{00b6}' | '\u{00b7}' | '\u{00bb}'
        | '\u{00bf}' | '\u{2010}'..='\u{2027}' | '\u{2030}'..='\u{205e}'
        | '\u{2e00}'..='\u{2e7f}' | '\u{3001}'..='\u{3003}' | '\u{3008}'..='\u{3011}'
        | '\u{ff01}'..='\u{ff03}' | '\u{ff05}'..='\u{ff0a}' | '\u{ff0c}'..='\u{ff0f}'
        | '\u{ff1a}' | '\u{ff1b}' | '\u{ff1f}' | '\u{ff20}' | '\u{ff3b}'..='\u{ff3d}')
}

pub fn is_symbol_char(c: char) -> bool {
    if c.is_ascii() {
        return matches!(c, '$' | '+' | '<' | '=' | '>' | '^' | '`' | '|' | '~');
    }
    matches!(c,
        '\u{00a2}'..='\u{00a6}' | '\u{00a8}' | '\u{00a9}' | '\u{00ac}' | '\u{00ae}'..='\u{00b1}'
        | '\u{00b4}' | '\u{00b8}' | '\u{00d7}' | '\u{00f7}' | '\u{2044}' | '\u{20a0}'..='\u{20bf}'
        | '\u{2100}'..='\u{214f}' | '\u{2190}'..='\u{2bff}' | '\u{3004}' | '\u{fb29}'
        | '\u{fe62}' | '\u{fe64}'..='\u{fe66}' | '\u{ff04}' | '\u{ff0b}' | '\u{ff1c}'..='\u{ff1e}')
}

fn is_punct_or_symbol(c: char) -> bool {
    is_punct_char(c) || is_symbol_char(c)
}

fn unicode_prop_matches(p: UnicodeProp, c: char) -> bool {
    use UnicodeProp::*;
    match p {
        Letter | Alphabetic => c.is_alphabetic(),
        LetterUpper => c.is_uppercase(),
        LetterLower => c.is_lowercase(),
        LetterTitle => matches!(c, '\u{01c5}' | '\u{01c8}' | '\u{01cb}' | '\u{01f2}'),
        LetterModifier => matches!(c, '\u{02b0}'..='\u{02ff}' | '\u{0374}' | '\u{037a}' | '\u{ff9e}' | '\u{ff9f}'),
        LetterOther => {
            c.is_alphabetic() && !c.is_uppercase() && !c.is_lowercase()
        }
        Mark => is_mark(c),
        Number => c.is_numeric(),
        NumberDecimal => is_decimal(c),
        Punctuation => is_punct_char(c),
        Symbol => is_symbol_char(c),
        Separator => c.is_whitespace() && c != '\t',
        SeparatorSpace => c == ' ' || (!c.is_ascii() && c.is_whitespace() && c != '\u{2028}' && c != '\u{2029}'),
        Other | Control => c.is_control(),
        Whitespace => is_regex_space(c),
        Latin => matches!(c, 'a'..='z' | 'A'..='Z' | '\u{00c0}'..='\u{024f}' | '\u{1e00}'..='\u{1eff}'),
        Greek => matches!(c, '\u{0370}'..='\u{03ff}' | '\u{1f00}'..='\u{1fff}'),
        Cyrillic => matches!(c, '\u{0400}'..='\u{04ff}' | '\u{0500}'..='\u{052f}'),
        Han => matches!(c, '\u{4e00}'..='\u{9fff}' | '\u{3400}'..='\u{4dbf}' | '\u{f900}'..='\u{fa6d}'),
        Arabic => matches!(c, '\u{0600}'..='\u{06ff}' | '\u{0750}'..='\u{077f}'),
        Hebrew => matches!(c, '\u{0590}'..='\u{05ff}'),
        Hiragana => matches!(c, '\u{3041}'..='\u{309f}'),
        Katakana => matches!(c, '\u{30a0}'..='\u{30ff}'),
        Any => true,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Anchor {
    /// `^`
    LineStart,
    /// `$`
    LineEnd,
    /// `\A`
    TextStart,
    /// `\z`
    TextEnd,
    /// `\Z`, i.e. end of text allowing a single trailing newline.
    TextEndSoft,
    /// `\b`
    WordBoundary,
    /// `\B`
    NotWordBoundary,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LookDir {
    Ahead,
    Behind,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Node {
    Empty,
    /// A literal string. Multiple adjacent literals are folded together by the
    /// parser to keep the matcher's continuation chains short.
    Literal { chars: Vec<char>, case_insensitive: bool },
    Class(Class),
    /// `.`
    Any { dot_all: bool },
    Concat(Vec<Node>),
    Alt(Vec<Node>),
    Repeat {
        node: Box<Node>,
        min: u32,
        max: Option<u32>,
        greedy: bool,
    },
    Group {
        index: Option<usize>,
        node: Box<Node>,
    },
    Atomic(Box<Node>),
    Look {
        dir: LookDir,
        negate: bool,
        node: Box<Node>,
    },
    Backref(usize),
    Anchor(Anchor),
}

