//! Parser turning a pattern string into a [`Node`] tree.

use super::ast::*;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParseError {
    pub pos: usize,
    pub message: String,
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Parsing error at position {}: {}", self.pos, self.message)
    }
}

/// Errors the "inner" engine would raise once the tree is compiled. They are
/// reported with a distinct wording, mirroring the layered design of the
/// original.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CompileError(pub String);

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RegexError {
    Parse(ParseError),
    Compile(CompileError),
}

impl std::fmt::Display for RegexError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            RegexError::Parse(e) => write!(f, "{e}"),
            RegexError::Compile(e) => write!(f, "Error compiling regex: Regex error: {}", e.0),
        }
    }
}

#[derive(Debug, Clone, Copy)]
struct Flags {
    case_insensitive: bool,
    dot_all: bool,
    multi_line: bool,
    extended: bool,
    swap_greed: bool,
}

impl Default for Flags {
    fn default() -> Self {
        Self {
            case_insensitive: false,
            dot_all: false,
            multi_line: false,
            extended: false,
            swap_greed: false,
        }
    }
}

pub struct Parsed {
    pub node: Node,
    pub group_count: usize,
    pub group_names: Vec<(String, usize)>,
}

pub struct Parser<'a> {
    src: &'a [u8],
    chars: Vec<(usize, char)>,
    /// Index into `chars`.
    i: usize,
    group_count: usize,
    group_names: Vec<(String, usize)>,
}

impl<'a> Parser<'a> {
    pub fn new(pattern: &'a str) -> Self {
        Self {
            src: pattern.as_bytes(),
            chars: pattern.char_indices().collect(),
            i: 0,
            group_count: 0,
            group_names: Vec::new(),
        }
    }

    fn pos(&self) -> usize {
        match self.chars.get(self.i) {
            Some((b, _)) => *b,
            None => self.src.len(),
        }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.i).map(|(_, c)| *c)
    }

    fn peek_at(&self, n: usize) -> Option<char> {
        self.chars.get(self.i + n).map(|(_, c)| *c)
    }

    fn bump(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.i += 1;
        }
        c
    }

    fn eat(&mut self, c: char) -> bool {
        if self.peek() == Some(c) {
            self.i += 1;
            true
        } else {
            false
        }
    }

    fn err<T>(&self, pos: usize, msg: &str) -> Result<T, RegexError> {
        Err(RegexError::Parse(ParseError {
            pos,
            message: msg.to_string(),
        }))
    }

    pub fn parse(mut self) -> Result<Parsed, RegexError> {
        let flags = Flags::default();
        let node = self.parse_alt(flags)?;
        if self.i < self.chars.len() {
            return self.err(
                self.pos(),
                "General parsing error: end of string not reached",
            );
        }
        Ok(Parsed {
            node,
            group_count: self.group_count,
            group_names: self.group_names,
        })
    }

    fn parse_alt(&mut self, flags: Flags) -> Result<Node, RegexError> {
        let mut branches = vec![self.parse_concat(flags)?];
        while self.peek() == Some('|') {
            self.bump();
            branches.push(self.parse_concat(flags)?);
        }
        if branches.len() == 1 {
            Ok(branches.pop().unwrap())
        } else {
            Ok(Node::Alt(branches))
        }
    }

    fn parse_concat(&mut self, mut flags: Flags) -> Result<Node, RegexError> {
        let mut items: Vec<Node> = Vec::new();
        loop {
            match self.peek() {
                None | Some('|') | Some(')') => break,
                _ => {}
            }
            if flags.extended {
                let c = self.peek().unwrap();
                if c.is_whitespace() {
                    self.bump();
                    continue;
                }
                if c == '#' {
                    while let Some(c) = self.peek() {
                        if c == '\n' {
                            break;
                        }
                        self.bump();
                    }
                    continue;
                }
            }
            let op_pos = self.pos();
            match self.peek().unwrap() {
                '*' | '+' | '?' => {
                    return self.err(op_pos, "Target of repeat operator is invalid");
                }
                '{' if self.looks_like_repeat() => {
                    return self.err(op_pos, "Target of repeat operator is invalid");
                }
                _ => {}
            }
            let atom = self.parse_atom(&mut flags)?;
            let atom = match atom {
                Some(a) => a,
                // A flag-setting group such as `(?i)`: no node produced.
                None => continue,
            };
            let repeated = self.parse_repeat(atom, flags)?;
            items.push(repeated);
        }
        match items.len() {
            0 => Ok(Node::Empty),
            1 => Ok(items.pop().unwrap()),
            _ => Ok(Node::Concat(fold_literals(items))),
        }
    }

    fn looks_like_repeat(&self) -> bool {
        // `{` only starts a repetition when it is followed by `n`, `n,` or
        // `n,m` and a closing brace; otherwise it is a literal brace.
        let mut k = self.i + 1;
        let mut digits = 0;
        while let Some((_, c)) = self.chars.get(k) {
            if c.is_ascii_digit() {
                digits += 1;
                k += 1;
            } else {
                break;
            }
        }
        if digits == 0 {
            return false;
        }
        if let Some((_, ',')) = self.chars.get(k) {
            k += 1;
            while let Some((_, c)) = self.chars.get(k) {
                if c.is_ascii_digit() {
                    k += 1;
                } else {
                    break;
                }
            }
        }
        matches!(self.chars.get(k), Some((_, '}')))
    }

    fn parse_repeat(&mut self, atom: Node, flags: Flags) -> Result<Node, RegexError> {
        let mut node = atom;
        loop {
            let op_pos = self.pos();
            let (min, max) = match self.peek() {
                Some('*') => {
                    self.bump();
                    (0, None)
                }
                Some('+') => {
                    self.bump();
                    (1, None)
                }
                Some('?') => {
                    self.bump();
                    (0, Some(1))
                }
                Some('{') if self.looks_like_repeat() => {
                    self.bump();
                    let mut lo = String::new();
                    while let Some(c) = self.peek() {
                        if c.is_ascii_digit() {
                            lo.push(c);
                            self.bump();
                        } else {
                            break;
                        }
                    }
                    let lo_v: u32 = lo.parse().unwrap_or(u32::MAX);
                    let hi = if self.eat(',') {
                        let mut hi = String::new();
                        while let Some(c) = self.peek() {
                            if c.is_ascii_digit() {
                                hi.push(c);
                                self.bump();
                            } else {
                                break;
                            }
                        }
                        if hi.is_empty() {
                            None
                        } else {
                            Some(hi.parse::<u32>().unwrap_or(u32::MAX))
                        }
                    } else {
                        Some(lo_v)
                    };
                    self.eat('}');
                    if let Some(h) = hi {
                        if h < lo_v {
                            return Err(RegexError::Compile(CompileError(
                                "error parsing pattern 0".into(),
                            )));
                        }
                    }
                    if lo_v > 100_000 {
                        return Err(RegexError::Compile(CompileError(
                            "error building NFA".into(),
                        )));
                    }
                    (lo_v, hi)
                }
                _ => return Ok(node),
            };
            let mut greedy = !flags.swap_greed;
            if self.peek() == Some('?') {
                self.bump();
                greedy = !greedy;
            } else if self.peek() == Some('+') {
                // Possessive: model as an atomic group around a greedy repeat.
                self.bump();
                node = Node::Atomic(Box::new(Node::Repeat {
                    node: Box::new(node),
                    min,
                    max,
                    greedy: true,
                }));
                continue;
            }
            // A second, directly following repetition operator is invalid.
            if matches!(self.peek(), Some('*') | Some('+'))
                || (self.peek() == Some('{') && self.looks_like_repeat())
            {
                let p = self.pos();
                let _ = op_pos;
                return self.err(p, "Target of repeat operator is invalid");
            }
            node = Node::Repeat {
                node: Box::new(node),
                min,
                max,
                greedy,
            };
        }
    }

    /// Parses a single atom. Returns `None` for constructs that only mutate
    /// flags (`(?i)`) or are pure comments (`(?#...)`).
    fn parse_atom(&mut self, flags: &mut Flags) -> Result<Option<Node>, RegexError> {
        let start = self.pos();
        let c = self.bump().unwrap();
        let node = match c {
            '.' => Node::Any {
                dot_all: flags.dot_all,
            },
            '^' => Node::Anchor(if flags.multi_line {
                Anchor::LineStart
            } else {
                Anchor::TextStart
            }),
            '$' => Node::Anchor(if flags.multi_line {
                Anchor::LineEnd
            } else {
                Anchor::TextEnd
            }),
            '[' => Node::Class(self.parse_class(*flags)?),
            '(' => return self.parse_group(start, flags),
            '\\' => match self.parse_escape(*flags, false)? {
                Escaped::Char(ch) => Node::Literal {
                    chars: vec![ch],
                    case_insensitive: flags.case_insensitive,
                },
                Escaped::Class(cl) => Node::Class(cl),
                Escaped::Anchor(a) => Node::Anchor(a),
                Escaped::Backref(n) => Node::Backref(n),
            },
            other => Node::Literal {
                chars: vec![other],
                case_insensitive: flags.case_insensitive,
            },
        };
        Ok(Some(node))
    }

    fn parse_group(
        &mut self,
        open_pos: usize,
        outer_flags: &mut Flags,
    ) -> Result<Option<Node>, RegexError> {
        let mut flags = *outer_flags;
        if self.peek() == Some('?') {
            self.bump();
            match self.peek() {
                Some('#') => {
                    while let Some(c) = self.bump() {
                        if c == ')' {
                            return Ok(None);
                        }
                    }
                    return self.err(open_pos + 1, "Opening parenthesis without closing parenthesis");
                }
                Some(':') => {
                    self.bump();
                    let inner = self.parse_alt(flags)?;
                    self.expect_close(open_pos)?;
                    return Ok(Some(Node::Group {
                        index: None,
                        node: Box::new(inner),
                    }));
                }
                Some('>') => {
                    self.bump();
                    let inner = self.parse_alt(flags)?;
                    self.expect_close(open_pos)?;
                    return Ok(Some(Node::Atomic(Box::new(inner))));
                }
                Some('=') => {
                    self.bump();
                    let inner = self.parse_alt(flags)?;
                    self.expect_close(open_pos)?;
                    return Ok(Some(Node::Look {
                        dir: LookDir::Ahead,
                        negate: false,
                        node: Box::new(inner),
                    }));
                }
                Some('!') => {
                    self.bump();
                    let inner = self.parse_alt(flags)?;
                    self.expect_close(open_pos)?;
                    return Ok(Some(Node::Look {
                        dir: LookDir::Ahead,
                        negate: true,
                        node: Box::new(inner),
                    }));
                }
                Some('<') if matches!(self.peek_at(1), Some('=') | Some('!')) => {
                    self.bump();
                    let negate = self.bump() == Some('!');
                    let inner = self.parse_alt(flags)?;
                    self.expect_close(open_pos)?;
                    return Ok(Some(Node::Look {
                        dir: LookDir::Behind,
                        negate,
                        node: Box::new(inner),
                    }));
                }
                Some('<') | Some('\'') => {
                    let name = self.parse_group_name(open_pos)?;
                    self.group_count += 1;
                    let idx = self.group_count;
                    self.group_names.push((name, idx));
                    let inner = self.parse_alt(flags)?;
                    self.expect_close(open_pos)?;
                    return Ok(Some(Node::Group {
                        index: Some(idx),
                        node: Box::new(inner),
                    }));
                }
                Some('P') => {
                    self.bump();
                    if self.peek() != Some('<') {
                        return self.err(open_pos, "Could not parse group name");
                    }
                    let name = self.parse_group_name(open_pos)?;
                    self.group_count += 1;
                    let idx = self.group_count;
                    self.group_names.push((name, idx));
                    let inner = self.parse_alt(flags)?;
                    self.expect_close(open_pos)?;
                    return Ok(Some(Node::Group {
                        index: Some(idx),
                        node: Box::new(inner),
                    }));
                }
                _ => {
                    // Flag group: `(?imsx)` or `(?imsx:...)` or `(?-i)`.
                    let mut negate = false;
                    loop {
                        match self.peek() {
                            Some('i') => {
                                self.bump();
                                flags.case_insensitive = !negate;
                            }
                            Some('m') => {
                                self.bump();
                                flags.multi_line = !negate;
                            }
                            Some('s') => {
                                self.bump();
                                flags.dot_all = !negate;
                            }
                            Some('x') => {
                                self.bump();
                                flags.extended = !negate;
                            }
                            Some('U') => {
                                self.bump();
                                flags.swap_greed = !negate;
                            }
                            Some('R') | Some('u') => {
                                self.bump();
                            }
                            Some('-') => {
                                self.bump();
                                negate = true;
                            }
                            Some(':') => {
                                self.bump();
                                let inner = self.parse_alt(flags)?;
                                self.expect_close(open_pos)?;
                                return Ok(Some(Node::Group {
                                    index: None,
                                    node: Box::new(inner),
                                }));
                            }
                            Some(')') => {
                                self.bump();
                                *outer_flags = flags;
                                return Ok(None);
                            }
                            None => {
                                return self.err(
                                    open_pos + 1,
                                    "Opening parenthesis without closing parenthesis",
                                )
                            }
                            Some(_) => {
                                return self.err(open_pos, "Could not parse group name");
                            }
                        }
                    }
                }
            }
        }
        self.group_count += 1;
        let idx = self.group_count;
        let inner = self.parse_alt(flags)?;
        self.expect_close(open_pos)?;
        Ok(Some(Node::Group {
            index: Some(idx),
            node: Box::new(inner),
        }))
    }

    fn parse_group_name(&mut self, open_pos: usize) -> Result<String, RegexError> {
        let close = match self.bump() {
            Some('<') => '>',
            Some('\'') => '\'',
            _ => return self.err(open_pos, "Could not parse group name"),
        };
        let mut name = String::new();
        loop {
            match self.bump() {
                Some(c) if c == close => break,
                Some(c) if c.is_alphanumeric() || c == '_' => name.push(c),
                Some(_) | None => return self.err(open_pos, "Could not parse group name"),
            }
        }
        if name.is_empty() {
            return self.err(open_pos, "Could not parse group name");
        }
        Ok(name)
    }

    fn expect_close(&mut self, open_pos: usize) -> Result<(), RegexError> {
        if self.eat(')') {
            Ok(())
        } else {
            self.err(
                open_pos + 1,
                "Opening parenthesis without closing parenthesis",
            )
        }
    }

    fn parse_class(&mut self, flags: Flags) -> Result<Class, RegexError> {
        let mut class = Class::new(false, flags.case_insensitive);
        if self.eat('^') {
            class.negated = true;
        }
        let mut first = true;
        loop {
            let Some(c) = self.peek() else {
                return self.err(self.pos(), "Invalid character class");
            };
            if c == ']' && !first {
                self.bump();
                break;
            }
            first = false;
            // POSIX bracket expression.
            if c == '[' && self.peek_at(1) == Some(':') {
                if let Some(name) = self.try_posix_class() {
                    let (neg, pred) = name;
                    if neg {
                        class.neg_preds.push(pred);
                    } else {
                        class.preds.push(pred);
                    }
                    continue;
                }
            }
            let lo = if c == '\\' {
                self.bump();
                match self.parse_escape(flags, true)? {
                    Escaped::Char(ch) => ch,
                    Escaped::Class(inner) => {
                        for p in inner.preds {
                            if inner.negated {
                                class.neg_preds.push(p);
                            } else {
                                class.preds.push(p);
                            }
                        }
                        for p in inner.neg_preds {
                            if inner.negated {
                                class.preds.push(p);
                            } else {
                                class.neg_preds.push(p);
                            }
                        }
                        for it in inner.items {
                            class.items.push(it);
                        }
                        continue;
                    }
                    Escaped::Anchor(_) | Escaped::Backref(_) => {
                        return self.err(self.pos(), "Invalid character class")
                    }
                }
            } else {
                self.bump();
                c
            };
            // Range?
            if self.peek() == Some('-')
                && self.peek_at(1).is_some()
                && self.peek_at(1) != Some(']')
            {
                self.bump();
                let hc = self.peek().unwrap();
                let hi = if hc == '\\' {
                    self.bump();
                    match self.parse_escape(flags, true)? {
                        Escaped::Char(ch) => ch,
                        _ => return self.err(self.pos(), "Invalid character class"),
                    }
                } else {
                    self.bump();
                    hc
                };
                if hi < lo {
                    return Err(RegexError::Compile(CompileError(
                        "error parsing pattern 0".into(),
                    )));
                }
                class.items.push(ClassItem::Range(lo, hi));
            } else {
                class.items.push(ClassItem::Single(lo));
            }
        }
        Ok(class)
    }

    fn try_posix_class(&mut self) -> Option<(bool, ClassPred)> {
        let save = self.i;
        self.i += 2; // `[:`
        let neg = self.peek() == Some('^');
        if neg {
            self.i += 1;
        }
        let mut name = String::new();
        while let Some(c) = self.peek() {
            if c.is_ascii_alphabetic() {
                name.push(c);
                self.i += 1;
            } else {
                break;
            }
        }
        if self.peek() == Some(':') && self.peek_at(1) == Some(']') {
            self.i += 2;
            let pred = match name.as_str() {
                "alpha" => ClassPred::Alpha,
                "digit" => ClassPred::Digit,
                "alnum" => ClassPred::Alnum,
                "space" => ClassPred::Space,
                "upper" => ClassPred::Upper,
                "lower" => ClassPred::Lower,
                "punct" => ClassPred::Punct,
                "graph" => ClassPred::Graph,
                "print" => ClassPred::Print,
                "blank" => ClassPred::Blank,
                "cntrl" => ClassPred::Cntrl,
                "xdigit" => ClassPred::XDigit,
                "word" => ClassPred::Word,
                "ascii" => ClassPred::Ascii,
                _ => {
                    self.i = save;
                    return None;
                }
            };
            return Some((neg, pred));
        }
        self.i = save;
        None
    }

    fn parse_escape(&mut self, flags: Flags, in_class: bool) -> Result<Escaped, RegexError> {
        let Some(c) = self.bump() else {
            return self.err(self.pos(), "General parsing error: trailing backslash");
        };
        let simple_class = |pred: ClassPred, negated: bool| {
            let mut cl = Class::new(negated, false);
            cl.preds.push(pred);
            Escaped::Class(cl)
        };
        Ok(match c {
            'd' => simple_class(ClassPred::Digit, false),
            'D' => simple_class(ClassPred::Digit, true),
            'w' => simple_class(ClassPred::Word, false),
            'W' => simple_class(ClassPred::Word, true),
            's' => simple_class(ClassPred::Space, false),
            'S' => simple_class(ClassPred::Space, true),
            'h' => simple_class(ClassPred::Blank, false),
            'H' => simple_class(ClassPred::Blank, true),
            'n' => Escaped::Char('\n'),
            'r' => Escaped::Char('\r'),
            't' => Escaped::Char('\t'),
            'f' => Escaped::Char('\u{c}'),
            'v' => Escaped::Char('\u{b}'),
            'a' => Escaped::Char('\u{7}'),
            'e' => Escaped::Char('\u{1b}'),
            '0' => Escaped::Char('\0'),
            'b' if in_class => Escaped::Char('\u{8}'),
            'b' => Escaped::Anchor(Anchor::WordBoundary),
            'B' if in_class => return self.err(self.pos(), "Invalid character class"),
            'B' => Escaped::Anchor(Anchor::NotWordBoundary),
            'A' if !in_class => Escaped::Anchor(Anchor::TextStart),
            'z' if !in_class => Escaped::Anchor(Anchor::TextEnd),
            'Z' if !in_class => Escaped::Anchor(Anchor::TextEndSoft),
            'x' => {
                let ch = self.parse_hex_escape()?;
                Escaped::Char(ch)
            }
            'u' => {
                let ch = self.parse_unicode_escape(4)?;
                Escaped::Char(ch)
            }
            'U' => {
                let ch = self.parse_unicode_escape(8)?;
                Escaped::Char(ch)
            }
            'p' | 'P' => {
                let negated = c == 'P';
                let prop = self.parse_unicode_prop()?;
                let mut cl = Class::new(negated, false);
                cl.preds.push(ClassPred::Unicode(prop));
                Escaped::Class(cl)
            }
            '1'..='9' if !in_class => {
                let mut n = c.to_digit(10).unwrap() as usize;
                while let Some(d) = self.peek().and_then(|c| c.to_digit(10)) {
                    let cand = n * 10 + d as usize;
                    if cand > self.group_count {
                        break;
                    }
                    n = cand;
                    self.bump();
                }
                Escaped::Backref(n)
            }
            other => {
                let _ = flags;
                Escaped::Char(other)
            }
        })
    }

    fn parse_hex_escape(&mut self) -> Result<char, RegexError> {
        if self.eat('{') {
            let mut s = String::new();
            while let Some(c) = self.peek() {
                if c == '}' {
                    break;
                }
                s.push(c);
                self.bump();
            }
            self.eat('}');
            let v = u32::from_str_radix(&s, 16)
                .map_err(|_| RegexError::Compile(CompileError("error parsing pattern 0".into())))?;
            return char::from_u32(v)
                .ok_or_else(|| RegexError::Compile(CompileError("error parsing pattern 0".into())));
        }
        let mut s = String::new();
        for _ in 0..2 {
            if let Some(c) = self.peek() {
                if c.is_ascii_hexdigit() {
                    s.push(c);
                    self.bump();
                }
            }
        }
        let v = u32::from_str_radix(&s, 16)
            .map_err(|_| RegexError::Compile(CompileError("error parsing pattern 0".into())))?;
        char::from_u32(v)
            .ok_or_else(|| RegexError::Compile(CompileError("error parsing pattern 0".into())))
    }

    fn parse_unicode_escape(&mut self, n: usize) -> Result<char, RegexError> {
        if self.peek() == Some('{') {
            return self.parse_hex_escape();
        }
        let mut s = String::new();
        for _ in 0..n {
            if let Some(c) = self.peek() {
                if c.is_ascii_hexdigit() {
                    s.push(c);
                    self.bump();
                }
            }
        }
        let v = u32::from_str_radix(&s, 16)
            .map_err(|_| RegexError::Compile(CompileError("error parsing pattern 0".into())))?;
        char::from_u32(v)
            .ok_or_else(|| RegexError::Compile(CompileError("error parsing pattern 0".into())))
    }

    fn parse_unicode_prop(&mut self) -> Result<UnicodeProp, RegexError> {
        let mut name = String::new();
        if self.eat('{') {
            while let Some(c) = self.peek() {
                if c == '}' {
                    break;
                }
                name.push(c);
                self.bump();
            }
            if !self.eat('}') {
                return Err(RegexError::Compile(CompileError(
                    "error parsing pattern 0".into(),
                )));
            }
        } else if let Some(c) = self.bump() {
            name.push(c);
        }
        let cleaned: String = name
            .chars()
            .filter(|c| *c != '_' && *c != '-' && *c != ' ')
            .collect::<String>()
            .to_ascii_lowercase();
        let cleaned = cleaned.strip_prefix("sc=").unwrap_or(&cleaned).to_string();
        let cleaned = cleaned.strip_prefix("script=").unwrap_or(&cleaned).to_string();
        let cleaned = cleaned.strip_prefix("gc=").unwrap_or(&cleaned).to_string();
        use UnicodeProp::*;
        Ok(match cleaned.as_str() {
            "l" | "letter" => Letter,
            "lu" | "uppercaseletter" => LetterUpper,
            "ll" | "lowercaseletter" => LetterLower,
            "lt" | "titlecaseletter" => LetterTitle,
            "lm" | "modifierletter" => LetterModifier,
            "lo" | "otherletter" => LetterOther,
            "m" | "mark" | "mn" | "mc" | "me" | "combiningmark" => Mark,
            "n" | "number" => Number,
            "nd" | "decimalnumber" => NumberDecimal,
            "p" | "punctuation" | "punct" => Punctuation,
            "s" | "symbol" => Symbol,
            "z" | "separator" => Separator,
            "zs" | "spaceseparator" => SeparatorSpace,
            "c" | "other" => Other,
            "cc" | "control" => Control,
            "whitespace" | "whitespaces" | "space" => Whitespace,
            "alphabetic" | "alpha" => Alphabetic,
            "latin" => Latin,
            "greek" => Greek,
            "cyrillic" => Cyrillic,
            "han" => Han,
            "arabic" => Arabic,
            "hebrew" => Hebrew,
            "hiragana" => Hiragana,
            "katakana" => Katakana,
            "any" => Any,
            _ => {
                return Err(RegexError::Compile(CompileError(
                    "error parsing pattern 0".into(),
                )))
            }
        })
    }
}

enum Escaped {
    Char(char),
    Class(Class),
    Anchor(Anchor),
    Backref(usize),
}

/// Merges runs of single-character literals into one node.
fn fold_literals(items: Vec<Node>) -> Vec<Node> {
    let mut out: Vec<Node> = Vec::with_capacity(items.len());
    for item in items {
        if let Node::Literal {
            chars,
            case_insensitive,
        } = &item
        {
            if let Some(Node::Literal {
                chars: prev,
                case_insensitive: prev_ci,
            }) = out.last_mut()
            {
                if *prev_ci == *case_insensitive {
                    prev.extend_from_slice(chars);
                    continue;
                }
            }
        }
        out.push(item);
    }
    out
}

