//! Backtracking matcher. Positions are indices into a `Vec<char>` view of the
//! haystack; byte offsets are recovered afterwards via a side table.

use super::ast::*;

pub struct Input<'a> {
    pub chars: Vec<char>,
    /// Byte offset of each char, plus a final entry for the end of input.
    pub offsets: Vec<usize>,
    pub text: &'a str,
}

impl<'a> Input<'a> {
    pub fn new(text: &'a str) -> Self {
        let mut chars = Vec::new();
        let mut offsets = Vec::new();
        for (b, c) in text.char_indices() {
            offsets.push(b);
            chars.push(c);
        }
        offsets.push(text.len());
        Self {
            chars,
            offsets,
            text,
        }
    }

    pub fn len(&self) -> usize {
        self.chars.len()
    }
}

struct State {
    caps: Vec<Option<(usize, usize)>>,
    steps: u64,
}

enum Cont<'a> {
    Done,
    Seq {
        nodes: &'a [Node],
        next: &'a Cont<'a>,
    },
    CloseGroup {
        index: usize,
        start: usize,
        next: &'a Cont<'a>,
    },
    Repeat {
        node: &'a Node,
        min: u32,
        max: Option<u32>,
        greedy: bool,
        count: u32,
        body_start: usize,
        next: &'a Cont<'a>,
    },
    /// Used by look-behind: succeed only when the given position is reached.
    RequirePos {
        pos: usize,
    },
}

const STEP_LIMIT: u64 = 40_000_000;

pub struct Matcher<'p> {
    pub root: &'p Node,
    pub group_count: usize,
}

impl<'p> Matcher<'p> {
    /// Attempts a match anchored at `at`. Returns the end position and captures.
    pub fn match_at(
        &self,
        input: &Input,
        at: usize,
    ) -> Option<(usize, Vec<Option<(usize, usize)>>)> {
        let mut st = State {
            caps: vec![None; self.group_count + 1],
            steps: 0,
        };
        let end = self.m_node(input, self.root, at, &mut st, &Cont::Done)?;
        st.caps[0] = Some((at, end));
        Some((end, st.caps))
    }

    fn run_cont(
        &self,
        input: &Input,
        pos: usize,
        st: &mut State,
        k: &Cont,
    ) -> Option<usize> {
        st.steps += 1;
        if st.steps > STEP_LIMIT {
            return None;
        }
        match k {
            Cont::Done => Some(pos),
            Cont::RequirePos { pos: want } => {
                if pos == *want {
                    Some(pos)
                } else {
                    None
                }
            }
            Cont::Seq { nodes, next } => self.m_seq(input, nodes, pos, st, next),
            Cont::CloseGroup { index, start, next } => {
                let saved = st.caps[*index];
                st.caps[*index] = Some((*start, pos));
                match self.run_cont(input, pos, st, next) {
                    Some(e) => Some(e),
                    None => {
                        st.caps[*index] = saved;
                        None
                    }
                }
            }
            Cont::Repeat {
                node,
                min,
                max,
                greedy,
                count,
                body_start,
                next,
            } => {
                if pos == *body_start && *count > *min {
                    // The body matched the empty string: stop iterating.
                    return self.run_cont(input, pos, st, next);
                }
                self.step_repeat(input, node, *min, *max, *greedy, *count, pos, st, next)
            }
        }
    }

    fn m_seq(
        &self,
        input: &Input,
        nodes: &[Node],
        pos: usize,
        st: &mut State,
        k: &Cont,
    ) -> Option<usize> {
        match nodes.split_first() {
            None => self.run_cont(input, pos, st, k),
            Some((head, rest)) => {
                let k2 = Cont::Seq { nodes: rest, next: k };
                self.m_node(input, head, pos, st, &k2)
            }
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn step_repeat(
        &self,
        input: &Input,
        node: &Node,
        min: u32,
        max: Option<u32>,
        greedy: bool,
        count: u32,
        pos: usize,
        st: &mut State,
        next: &Cont,
    ) -> Option<usize> {
        let can_more = max.map_or(true, |m| count < m);
        if count < min {
            let k = Cont::Repeat {
                node,
                min,
                max,
                greedy,
                count: count + 1,
                body_start: pos,
                next,
            };
            return self.m_node(input, node, pos, st, &k);
        }
        if greedy {
            if can_more {
                let k = Cont::Repeat {
                    node,
                    min,
                    max,
                    greedy,
                    count: count + 1,
                    body_start: pos,
                    next,
                };
                if let Some(e) = self.m_node(input, node, pos, st, &k) {
                    return Some(e);
                }
            }
            self.run_cont(input, pos, st, next)
        } else {
            if let Some(e) = self.run_cont(input, pos, st, next) {
                return Some(e);
            }
            if can_more {
                let k = Cont::Repeat {
                    node,
                    min,
                    max,
                    greedy,
                    count: count + 1,
                    body_start: pos,
                    next,
                };
                return self.m_node(input, node, pos, st, &k);
            }
            None
        }
    }

    fn m_node(
        &self,
        input: &Input,
        node: &Node,
        pos: usize,
        st: &mut State,
        k: &Cont,
    ) -> Option<usize> {
        st.steps += 1;
        if st.steps > STEP_LIMIT {
            return None;
        }
        match node {
            Node::Empty => self.run_cont(input, pos, st, k),
            Node::Literal {
                chars,
                case_insensitive,
            } => {
                let mut p = pos;
                for want in chars {
                    let got = *input.chars.get(p)?;
                    if got == *want {
                        p += 1;
                        continue;
                    }
                    if *case_insensitive && chars_eq_fold(got, *want) {
                        p += 1;
                        continue;
                    }
                    return None;
                }
                self.run_cont(input, p, st, k)
            }
            Node::Class(cl) => {
                let got = *input.chars.get(pos)?;
                if cl.matches(got) {
                    self.run_cont(input, pos + 1, st, k)
                } else {
                    None
                }
            }
            Node::Any { dot_all } => {
                let got = *input.chars.get(pos)?;
                if !*dot_all && got == '\n' {
                    return None;
                }
                self.run_cont(input, pos + 1, st, k)
            }
            Node::Concat(items) => self.m_seq(input, items, pos, st, k),
            Node::Alt(branches) => {
                for b in branches {
                    if let Some(e) = self.m_node(input, b, pos, st, k) {
                        return Some(e);
                    }
                }
                None
            }
            Node::Repeat {
                node,
                min,
                max,
                greedy,
            } => self.step_repeat(input, node, *min, *max, *greedy, 0, pos, st, k),
            Node::Group { index, node } => match index {
                None => self.m_node(input, node, pos, st, k),
                Some(idx) => {
                    let k2 = Cont::CloseGroup {
