                    Some(e) => match self.run_cont(input, e, st, k) {
                        Some(fin) => Some(fin),
                        None => {
                            st.caps = saved;
                            None
                        }
                    },
                    None => {
                        st.caps = saved;
                        None
                    }
                }
            }
            Node::Look { dir, negate, node } => {
                let saved = st.caps.clone();
                let hit = match dir {
                    LookDir::Ahead => self
                        .m_node(input, node, pos, st, &Cont::Done)
                        .is_some(),
                    LookDir::Behind => {
                        let (lo, hi) = look_behind_span(node);
                        let mut found = false;
                        let max_back = hi.unwrap_or(pos as u32).min(pos as u32);
                        let min_back = lo.min(pos as u32);
                        let mut back = min_back;
                        while back <= max_back {
                            let start = pos - back as usize;
                            let kk = Cont::RequirePos { pos };
                            if self.m_node(input, node, start, st, &kk).is_some() {
                                found = true;
                                break;
                            }
                            back += 1;
                        }
                        found
                    }
                };
                if hit == *negate {
                    st.caps = saved;
                    return None;
                }
                if *negate {
                    st.caps = saved;
                }
                match self.run_cont(input, pos, st, k) {
                    Some(e) => Some(e),
                    None => {
                        st.caps = saved;
