fn chars_eq_fold(a: char, b: char) -> bool {
    if a == b {
        return true;
    }
    let av = fold_variants(a);
    av.contains(&b)
}

fn is_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

fn anchor_holds(input: &Input, a: Anchor, pos: usize) -> bool {
    match a {
        Anchor::TextStart => pos == 0,
        Anchor::TextEnd => pos == input.len(),
        Anchor::TextEndSoft => {
