        Node::Class(_) | Node::Any { .. } => (1, Some(1)),
        Node::Backref(_) => (0, None),
        Node::Concat(items) => {
            let mut lo = 0u32;
            let mut hi = Some(0u32);
            for it in items {
                let (l, h) = look_behind_span(it);
                lo = lo.saturating_add(l);
                hi = match (hi, h) {
                    (Some(a), Some(b)) => Some(a.saturating_add(b)),
                    _ => None,
                };
            }
            (lo, hi)
        }
        Node::Alt(branches) => {
            let mut lo = u32::MAX;
            let mut hi = Some(0u32);
            for b in branches {
                let (l, h) = look_behind_span(b);
                lo = lo.min(l);
                hi = match (hi, h) {
                    (Some(a), Some(b)) => Some(a.max(b)),
                    _ => None,
                };
            }
            (if lo == u32::MAX { 0 } else { lo }, hi)
        }
        Node::Repeat { node, min, max, .. } => {
            let (l, h) = look_behind_span(node);
            let lo = l.saturating_mul(*min);
            let hi = match (h, max) {
                (Some(h), Some(m)) => Some(h.saturating_mul(*m)),
                _ => None,
            };
            (lo, hi)
        }
        Node::Group { node, .. } | Node::Atomic(node) => look_behind_span(node),
    }
}

