//! Backtracking matcher. Positions are indices into a `Vec<char>` view of the
//! haystack; byte offsets are recovered afterwards via a side table.

use super::ast::*;

pub struct Input<'a> {
    pub chars: Vec<char>,
    /// Byte offset of each char, plus a final entry for the end of input.
    pub offsets: Vec<usize>,
    pub text: &'a str,
}

impl<'a> Input<'a> {
    pub fn new(text: &'a str) -> Self {
        let mut chars = Vec::new();
        let mut offsets = Vec::new();
        for (b, c) in text.char_indices() {
            offsets.push(b);
            chars.push(c);
        }
        offsets.push(text.len());
        Self {
            chars,
            offsets,
            text,
        }
    }

    pub fn len(&self) -> usize {
        self.chars.len()
    }
}

struct State {
    caps: Vec<Option<(usize, usize)>>,
    steps: u64,
}

enum Cont<'a> {
    Done,
    Seq {
        nodes: &'a [Node],
        next: &'a Cont<'a>,
    },
    CloseGroup {
        index: usize,
        start: usize,
        next: &'a Cont<'a>,
    },
    Repeat {
        node: &'a Node,
        min: u32,
        max: Option<u32>,
        greedy: bool,
        count: u32,
        body_start: usize,
        next: &'a Cont<'a>,
    },
    /// Used by look-behind: succeed only when the given position is reached.
    RequirePos {
        pos: usize,
    },
}

const STEP_LIMIT: u64 = 40_000_000;

pub struct Matcher<'p> {
    pub root: &'p Node,
    pub group_count: usize,
}

impl<'p> Matcher<'p> {
    /// Attempts a match anchored at `at`. Returns the end position and captures.
    pub fn match_at(
        &self,
        input: &Input,
        at: usize,
    ) -> Option<(usize, Vec<Option<(usize, usize)>>)> {
        let mut st = State {
            caps: vec![None; self.group_count + 1],
            steps: 0,
        };
        let end = self.m_node(input, self.root, at, &mut st, &Cont::Done)?;
        st.caps[0] = Some((at, end));
        Some((end, st.caps))
    }

    fn run_cont(
        &self,
        input: &Input,
        pos: usize,
        st: &mut State,
        k: &Cont,
    ) -> Option<usize> {
        st.steps += 1;
        if st.steps > STEP_LIMIT {
            return None;
        }
        match k {
            Cont::Done => Some(pos),
            Cont::RequirePos { pos: want } => {
                if pos == *want {
                    Some(pos)
                } else {
                    None
                }
            }
            Cont::Seq { nodes, next } => self.m_seq(input, nodes, pos, st, next),
            Cont::CloseGroup { index, start, next } => {
                let saved = st.caps[*index];
                st.caps[*index] = Some((*start, pos));
                match self.run_cont(input, pos, st, next) {
                    Some(e) => Some(e),
                    None => {
                        st.caps[*index] = saved;
                        None
                    }
                }
            }
            Cont::Repeat {
                node,
                min,
                max,
                greedy,
                count,
                body_start,
                next,
            } => {
                if pos == *body_start && *count > *min {
