            }
        }
    }

    fn m_seq(
        &self,
        input: &Input,
        nodes: &[Node],
        pos: usize,
        st: &mut State,
        k: &Cont,
    ) -> Option<usize> {
        match nodes.split_first() {
            None => self.run_cont(input, pos, st, k),
