                        while back <= max_back {
                            let start = pos - back as usize;
                            let kk = Cont::RequirePos { pos };
                            if self.m_node(input, node, start, st, &kk).is_some() {
                                found = true;
                                break;
                            }
                            back += 1;
                        }
                        found
                    }
                };
                if hit == *negate {
                    st.caps = saved;
                    return None;
                }
                if *negate {
                    st.caps = saved;
                }
