//! A small backtracking regular expression engine covering the dialect the
//! tool exposes to users: capture groups (numbered and named), look-around,
//! back-references, lazy/possessive quantifiers and inline flags.

pub mod ast;
pub mod exec;
pub mod parse;

use ast::Node;
use exec::{Input, Matcher};
pub use parse::RegexError;

pub struct Regex {
    root: Node,
    group_count: usize,
    group_names: Vec<(String, usize)>,
    pattern: String,
}

/// A single match: byte ranges for the whole match and each capture group.
#[derive(Debug, Clone)]
pub struct Captures {
    pub groups: Vec<Option<(usize, usize)>>,
}

impl Captures {
    pub fn start(&self) -> usize {
        self.groups[0].unwrap().0
    }
    pub fn end(&self) -> usize {
        self.groups[0].unwrap().1
    }
}

impl Regex {
    pub fn new(pattern: &str) -> Result<Self, RegexError> {
        let parsed = parse::Parser::new(pattern).parse()?;
        Ok(Self {
            root: parsed.node,
            group_count: parsed.group_count,
            group_names: parsed.group_names,
            pattern: pattern.to_string(),
        })
    }

    pub fn as_str(&self) -> &str {
        &self.pattern
    }

    pub fn captures_iter<'r, 't>(&'r self, text: &'t str) -> Vec<Captures> {
        let input = Input::new(text);
        let matcher = Matcher {
            root: &self.root,
            group_count: self.group_count,
        };
        let mut out = Vec::new();
        let mut at = 0usize;
        let n = input.len();
        loop {
            let mut found = None;
            let mut start = at;
            while start <= n {
                if let Some((end, caps)) = matcher.match_at(&input, start) {
                    found = Some((start, end, caps));
                    break;
                }
                start += 1;
            }
            let Some((start, end, caps)) = found else { break };
            let to_bytes = |r: Option<(usize, usize)>| {
                r.map(|(s, e)| (input.offsets[s], input.offsets[e]))
            };
            let groups: Vec<Option<(usize, usize)>> = caps.iter().map(|g| to_bytes(*g)).collect();
            out.push(Captures { groups });
            at = if end == start { end + 1 } else { end };
            if start > n {
                break;
            }
        }
        out
    }

    pub fn is_match(&self, text: &str) -> bool {
        let input = Input::new(text);
        let matcher = Matcher {
            root: &self.root,
            group_count: self.group_count,
        };
        let n = input.len();
        for start in 0..=n {
            if matcher.match_at(&input, start).is_some() {
                return true;
            }
        }
        false
    }

    pub fn name_index(&self, name: &str) -> Option<usize> {
        self.group_names
            .iter()
            .find(|(n, _)| n == name)
            .map(|(_, i)| *i)
    }

    /// Expands a replacement template against a match.
    pub fn expand(&self, text: &str, caps: &Captures, template: &str) -> String {
        let mut out = String::new();
        let bytes: Vec<char> = template.chars().collect();
        let mut i = 0;
        while i < bytes.len() {
            let c = bytes[i];
            if c != '$' {
                out.push(c);
                i += 1;
                continue;
            }
            i += 1;
            if i >= bytes.len() {
                out.push('$');
                break;
            }
            if bytes[i] == '$' {
                out.push('$');
                i += 1;
                continue;
            }
            let (name, consumed) = if bytes[i] == '{' {
                let mut j = i + 1;
                let mut name = String::new();
                while j < bytes.len() && bytes[j] != '}' {
                    name.push(bytes[j]);
                    j += 1;
                }
                if j >= bytes.len() {
                    // Unterminated: emit verbatim.
                    out.push('$');
                    out.push('{');
                    out.push_str(&name);
                    i = j;
                    continue;
                }
                (name, j + 1 - i)
            } else {
                let mut j = i;
                let mut name = String::new();
                while j < bytes.len() && (bytes[j].is_alphanumeric() || bytes[j] == '_') {
                    name.push(bytes[j]);
                    j += 1;
                }
                if name.is_empty() {
                    out.push('$');
                    continue;
                }
                (name, j - i)
            };
            i += consumed;
            let idx = if let Ok(n) = name.parse::<usize>() {
                Some(n)
            } else {
                self.name_index(&name)
            };
            if let Some(idx) = idx {
                if let Some(Some((s, e))) = caps.groups.get(idx) {
                    out.push_str(&text[*s..*e]);
                }
            }
        }
        out
    }
}

