        let input = Input::new(text);
        let matcher = Matcher {
            root: &self.root,
            group_count: self.group_count,
        };
        let mut out = Vec::new();
        let mut at = 0usize;
        let n = input.len();
        loop {
            let mut found = None;
            let mut start = at;
            while start <= n {
                if let Some((end, caps)) = matcher.match_at(&input, start) {
                    found = Some((start, end, caps));
                    break;
                }
                start += 1;
            }
            let Some((start, end, caps)) = found else { break };
            let to_bytes = |r: Option<(usize, usize)>| {
                r.map(|(s, e)| (input.offsets[s], input.offsets[e]))
            };
            let groups: Vec<Option<(usize, usize)>> = caps.iter().map(|g| to_bytes(*g)).collect();
            out.push(Captures { groups });
            at = if end == start { end + 1 } else { end };
            if start > n {
                break;
            }
        }
        out
    }

    pub fn is_match(&self, text: &str) -> bool {
        let input = Input::new(text);
        let matcher = Matcher {
            root: &self.root,
            group_count: self.group_count,
        };
        let n = input.len();
        for start in 0..=n {
            if matcher.match_at(&input, start).is_some() {
                return true;
            }
        }
        false
    }

    pub fn name_index(&self, name: &str) -> Option<usize> {
        self.group_names
            .iter()
            .find(|(n, _)| n == name)
            .map(|(_, i)| *i)
    }

    /// Expands a replacement template against a match.
    pub fn expand(&self, text: &str, caps: &Captures, template: &str) -> String {
        let mut out = String::new();
        let bytes: Vec<char> = template.chars().collect();
        let mut i = 0;
        while i < bytes.len() {
            let c = bytes[i];
            if c != '$' {
                out.push(c);
                i += 1;
                continue;
            }
            i += 1;
            if i >= bytes.len() {
                out.push('$');
                break;
            }
            if bytes[i] == '$' {
                out.push('$');
                i += 1;
                continue;
            }
            let (name, consumed) = if bytes[i] == '{' {
                let mut j = i + 1;
                let mut name = String::new();
                while j < bytes.len() && bytes[j] != '}' {
                    name.push(bytes[j]);
                    j += 1;
                }
                if j >= bytes.len() {
                    // Unterminated: emit verbatim.
                    out.push('$');
                    out.push('{');
                    out.push_str(&name);
                    i = j;
                    continue;
                }
                (name, j + 1 - i)
            } else {
                let mut j = i;
                let mut name = String::new();
                while j < bytes.len() && (bytes[j].is_alphanumeric() || bytes[j] == '_') {
                    name.push(bytes[j]);
                    j += 1;
                }
                if name.is_empty() {
                    out.push('$');
                    continue;
                }
                (name, j - i)
            };
            i += consumed;
            let idx = if let Ok(n) = name.parse::<usize>() {
                Some(n)
            } else {
                self.name_index(&name)
            };
            if let Some(idx) = idx {
                if let Some(Some((s, e))) = caps.groups.get(idx) {
                    out.push_str(&text[*s..*e]);
                }
            }
        }
        out
    }
}
